let rows = "";

for (const item of $input.all()) {
  const p = item.json;

  const nota     = p.nota_imdb  ? `⭐ ${p.nota_imdb}/10` : "Sin nota";
  const director = p.director   ? `🎭 ${p.director}`      : "";
  const sinopsis = p.sinopsis
    ? p.sinopsis.substring(0, 150) + (p.sinopsis.length > 150 ? "..." : "")
    : "Sin sinopsis disponible";
  const cines    = p.num_cines  ? `${p.num_cines} cines`  : "—";

  rows += `
    <tr>
      <td style="padding: 10px; border: 1px solid #ddd;">
        <b>${p.titulo}</b><br>
        <span style="color: #666; font-size: 0.85em;">${director}</span>
      </td>
      <td style="padding: 10px; border: 1px solid #ddd; text-align: center; color: #e6a817;">
        ${nota}
      </td>
      <td style="padding: 10px; border: 1px solid #ddd; font-size: 0.85em; color: #444;">
        ${sinopsis}
      </td>
      <td style="padding: 10px; border: 1px solid #ddd; text-align: center;">
        ${cines}<br>
        <a href="${p.url_ficha}" style="font-size: 0.85em;">Ver ficha</a>
        ${p.url_imdb ? `| <a href="${p.url_imdb}" style="font-size: 0.85em;">IMDB</a>` : ""}
      </td>
    </tr>`;
}

const fecha = new Date().toLocaleDateString("es-ES", {
  weekday: "long", year: "numeric", month: "long", day: "numeric"
});

// FIX: return con la estructura correcta de n8n
return [{
  json: {
    html_tabla: `
      <h2>🎬 Cartelera de Madrid</h2>
      <p>Recomendaciones para la semana del <b>${fecha}</b>:</p>
      <table style="width:100%; border-collapse: collapse; font-family: Arial, sans-serif;">
        <thead>
          <tr style="background-color: #1a1a2e; color: white;">
            <th style="padding: 10px; border: 1px solid #ddd; text-align: left;">Película</th>
            <th style="padding: 10px; border: 1px solid #ddd;">Nota IMDB</th>
            <th style="padding: 10px; border: 1px solid #ddd; text-align: left;">Sinopsis</th>
            <th style="padding: 10px; border: 1px solid #ddd;">Cines / Enlace</th>
          </tr>
        </thead>
        <tbody>
          ${rows}
        </tbody>
      </table>
      <p style="font-size: 0.8em; color: grey; margin-top: 16px;">
        Fuente: ecartelera.com + IMDB · Generado automáticamente cada lunes a las 9:00
      </p>`
  }
}];
